def fig(name,width=510,maxheight=None):
 path=O/'figures'/name;w,hh=PILImage.open(path).size
 if maxheight is not None:width=min(width,maxheight*w/hh)
 return Image(str(path),width=width,height=width*hh/w)
def table(rows,widths):
 t=Table([[p(str(x),'CellXY') for x in row] for row in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9f1f5')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#668799')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#d6e0e6'))]))
 return t
def footer(c,doc):
 c.setStrokeColor(colors.HexColor('#d6e0e6'));c.line(42,36,570,36)
 c.setFont('D',7.5);c.setFillColor(colors.HexColor('#526273'));c.drawString(42,24,'Constrained XY simulations | collaborator briefing | 16 October 2026');c.drawRightString(570,24,str(doc.page))
def build(name,story,landscape=False):
 size=(792,612) if landscape else (612,792)
 SimpleDocTemplate(str(O/name),pagesize=size,rightMargin=42,leftMargin=42,topMargin=35,bottomMargin=46,title='Constrained XY simulations: transition curves and spin scaling dimension',author='Luscher XY numerical study').build(story,onFirstPage=footer,onLaterPages=footer)

story=[]
story += [p('Constrained XY simulations','TitleXY'),p('Transition curves and the 3D spin scaling dimension','HeadXY'),p('Briefing for a collaborator’s talk | Results attained 13-15 October 2026. This is an exploratory numerical report, not a precision universality determination. All quantities and figures below use the saved, independently reviewed analyses; no new MC was generated for this report.')]
story += [fig('01-phase-boundaries-all-dimensions.png',440),p('<b>Figure 1.</b> Fixed-ε points have vertical bars; β=0 endpoints have horizontal bars. Dark: conditional MC95. Pale: descriptive sensitivity unions, including MC noise and model choices; these are not calibrated total 95% intervals. The open 5D square at ε/π=1 is a rejected-fit diagnostic. Panel scales differ.','CaptionXY')]
story += [h('What these results support'),p('The attained curves show a descriptive dimension-dependent approach toward the full tree-level prediction. The β=0 transition is at ε/π greater than 1/2 in every studied dimension. In 3D, common-correlation-length magnetization quotients give effective spin dimensions near <b>Δ ≈ 0.52</b>, compatible with the ordinary O(2) Wilson-Fisher expectation. A calibrated combined statistical-plus-systematic error has not been established.')]
story += [table([['Dimension','Positive-β estimates on the 0.02 ε/π grid','β=0 endpoint ε/π (approx.)'],['2','22: 0.58 through 1.00','0.559; broad model sensitivity'],['3','10: 0.82 through 1.00','0.801; finer crossing study on p. 3'],['4','7: 0.88 through 1.00','0.861; exploratory size fit'],['5','5 conditional: 0.90 through 0.98; 1.00 diagnostic only','0.893']], [57,291,180])]
story += [PageBreak(),p('Simulation and analysis methods','TitleXY')]
story += [h('Model, boundaries and sampling'),p('Angles φ on periodic hypercubic boxes of volume V=L<super>d</super>. The dimensionless action is S = -β Σ<sub>links</sub> cos θ, with θ = wrap(φ<sub>j</sub>-φ<sub>i</sub>) and the strict constraint |θ| &lt; ε. Thus β=0 removes the cosine weight but preserves the hard constraint; ε=π is the standard XY limit up to measure-zero configurations. L and N denote the same linear box size.'),p('<b>One recorded hybrid MC cycle</b> = one local Metropolis sweep (one proposal per site), four Wolff cluster reflections, and one random-axis/sign unit-winding proposal. Four clusters are not four volume sweeps. Each chain has its own seed; fresh pairs generally start in zero and unit axial winding backgrounds. Measurements follow every cycle. Update/replay tests and full-field closure audits check implementation and recorded observables; they do not prove equilibration or independent sampling.')]
story += [table([['Study','Linear sizes L','Recorded cycles per chain (including initial transient)'],['2D transition curves','Reused 16,32,64 anchors; new 64,128,256; 512 at ε/π=0.60,0.80,1 and β=0','New positive-β cohort: 416 × 12,000. Endpoint chains separate; legacy data retain their own analysis cuts. Completed 1024 probes excluded.'],['3D transition curves','Source 6,8,12,16,24,32; primary fits start at 6; 32 diagnostic','788-source positive-curve analysis: 786 × 4,000 and 2 × 16,000. Includes diagnostic/β=0 coordinates.'],['4D transition curves','6,8,10,12,16,20,24; primary positive fits L≥10','728-source analysis: 726 × 4,000 and 2 × 16,000. Includes diagnostic/β=0 coordinates.'],['5D transition curves','Pilot 4; primary 6,8,10,12','282 trajectories: 208 × 4,000 and 74 × 8,000. Adaptive, not a balanced rectangular grid.'],['3D β=0 spin dimension','6,8,12,16,24,32,48,64; largest new chains 48³ and 64³','270 pinned sources: 186 × 12,000; 44 × 20,000; 24 × 8,000; 16 × 4,000. No box above 64³.']], [95,175,258])]
story += [h('Observables and finite-size transition definitions'),p('Define m = V<super>-1</super>Σ exp(iφ). The O(2) Binder convention is U = 1 - ⟨|m|<super>4</super>⟩/[2⟨|m|²⟩²]. The second-moment ratio is R=ξ/L = √(⟨S(0)⟩/⟨F⟩-1)/[2L sin(π/L)], with F averaged over axial minimal momenta. Ratios are formed from ensemble moments, not averaged configuration-by-configuration ratios. Vortex density, all axial winding histories, energy-like observables and update diagnostics are also recorded.'),p('<b>2D:</b> local roots of R→0.7506912 and η<sub>eff</sub>(L,2L)=-ln[⟨|m|²⟩<sub>2L</sub>/⟨|m|²⟩<sub>L</sub>]/ln2 → 1/4; exploratory shifts proportional to (ln L+C)<super>-2</super>, shared infinite-volume limit and separate observable amplitudes. <b>3D/4D/5D:</b> local U=1/4 roots. Leading shift coordinates are respectively L<super>-1/0.67169</super>, L<super>-2</super>(ln L)<super>-1/10</super>, and L<super>-5/2</super>. Size cuts and correction terms are tested, not assumed validated. In 5D the zero-mode Binder value is 1-π/4≈0.2146, so 1/4 is a shifted fixed criterion.')]
story += [h('Statistical treatment'),p('Typical primary cuts discard cycles 0-1000 (3D/4D/5D curves and spin study); new 2D/endpoint analyses generally cut through 2000. Retained histories are resampled in contiguous autocorrelation-aware blocks separately within starts, then pooled by retained rows. Original 3D/4D positive curves use 1,000 bootstrap draws; 2D, 5D and spin analyses use 2,000. Typical nominal block width is max(20, ceil[10 max τ<sub>int</sub>]); the spin baseline doubles it and a further doubling is tested. Shared draws preserve covariance of derived observables and overlapping size pairs. Narrow intervals remain conditional on mixing, block choice, local windows and scaling laws.','SmallXY')]
story += [PageBreak(),p('3D at β=0: locating criticality','TitleXY')]
story += [p('The target is the scaling dimension of the charge-one spin operator exp(iφ), not the magnetization critical exponent β<sub>mag</sub>. In 3D, ⟨exp(iφ(x)) exp(-iφ(0))⟩ ∼ |x|<super>-2Δ</super>, with Δ=(1+η)/2. Correspondingly ⟨|m|²⟩ ∼ L<super>-2Δ</super>, up to finite-size corrections and analytic backgrounds.'),fig('09-four-size-correlation-length-crossing.png',510),p('<b>Figure 2.</b> All four large sizes on one axis. Each ξ/L response is fitted independently; neither a shared crossing nor a target critical R is imposed. Curves may have different finite-size crossings. The near-common intersection is useful evidence, not proof of an exact thermodynamic critical coupling.','CaptionXY')]
story += [h('Common-coupling quotient method'),p('For each pair L:2L, solve R<sub>L</sub>(q*)=R<sub>2L</sub>(q*) at the <b>same</b> q=ε/π. Then evaluate Δ<sub>eff</sub>=-ln[⟨|m|²⟩<sub>2L,q*</sub>/⟨|m|²⟩<sub>L,q*</sub>]/(2 ln2). This avoids matching magnetizations at different ε or imposing a universal Binder/R value. The final 120 trajectories refine common knots with fine interior spacing 0.000125; L=48,64 chains have 20,000 cycles.'),p('Noisy knot-by-knot interpolation can yield multiple crossings. The displayed results instead use weighted local quadratic responses for R and ⟨|m|²⟩ over q=0.800500-0.801500, with original joint bootstrap draws. Inner-window, linear, cut, block and start-parity alternatives are retained. A required root must be physical, unique in its window and present in at least 99% of bootstrap draws.')]
story += [table([['Finite size pair','Crossing q*','Δ_eff ± statistical SD'],['24:48','0.8007565','0.51598 ± 0.00292'],['32:64','0.8007428','0.51903 ± 0.00326']], [130,160,238]),Spacer(1,7),p('Both pairs retain 2,000/2,000 roots for each of the five broad-quadratic baseline/cut/block/start variants. They are correlated, not two independent estimates to average. Inner-quadratic 24:48 retains only 97% and remains unresolved; broad-linear fits fail the large-size curvature check. Thus the selected-family coverage does not validate all response choices.','SmallXY')]
story += [PageBreak(),p('Reading Δ and answering questions','TitleXY'),fig('10-magnetization-slope.png',505),p('<b>Figure 3.</b> A direct slope visualization at exactly measured q=0.80075: √⟨|m|²⟩ ∼ L<super>-Δ_eff</super>. Correlated fit over L=24,32,48,64 gives <b>Δ_eff=0.51942 ± 0.00795 stat</b> (one SD); conditional MC95 [0.50398,0.53505]. This fixed-q near-critical slope excludes uncertainty in thermodynamic criticality and scaling corrections.','CaptionXY')]
story += [h('How to quote the result'),p('<b>Suggested talk wording:</b> “At β=0, finite-size magnetization quotients and a direct magnetization slope give Δ near 0.52, compatible with the standard 3D O(2) Wilson-Fisher CFT. The statistical precision is a few 10<super>-3</super> for selected pair quotients, but finite-size and response-model uncertainty are not yet calibrated.” Do not turn this into Δ=0.52±0.01 as a formal confidence interval or quote an invented σ<sub>sys</sub>.'),p('Conditional correlated extrapolations with a fixed Wilson-Fisher-informed correction exponent ω=0.789 give 0.52321±0.00346 stat (minimum pair L=8) and 0.51834±0.00616 (minimum L=12); an inner-linear alternative gives 0.52057±0.00640. These are sensitivity examples, not a selected final CFT value. The raw unsmoothed 32:64 quotient is 0.52593±0.00572, with start-parity sensitivity; local regression changes the estimator. Literature comparison: Δ=0.519088(22) from conformal bootstrap [1], which also tabulates the MC result 0.519050(40). Neither was imposed as the measured Δ.')]
story += [PageBreak(),p('Questions and numerical context','TitleXY'),h('Qualifications worth saying aloud'),p('<b>What do the pale bars mean?</b> A descriptive union across tested cuts, thresholds, interpolants and scaling models, including amplified MC noise and some rejected-model diagnostics; not a systematic standard deviation or total confidence interval.<br/><b>What remains unresolved?</b> Absolute BKT accuracy: the 2D q=1 dark interval misses the known 1.1199 benchmark [2], although its wider union includes it. The 5D q=1 leading size fit rejects and is diagnostic only. Low independent-block counts, including as few as seven in some 5D starts, and start/half-history flags remain material.<br/><b>Why can order survive at β=0?</b> The angle constraint survives heating and can create entropic rigidity. Vortices being permitted at ε&gt;π/2 does not imply their macroscopic proliferation. In 2D say “massless/BKT phase,” not spontaneous magnetization.')]
story += [h('Attained β=0 endpoints'),table([['d','ε_c/π','Conditional MC95','Descriptive sensitivity union'],['2','0.55857','[0.55590, 0.56174]','[0.53629, 0.56855]'],['3','0.80108','[0.80076, 0.80144]','[0.79704, 0.80192]'],['4','0.86112','[0.86093, 0.86136]','[0.85622, 0.86346]'],['5','0.89320','[0.89303, 0.89332]','[0.89191, 0.89476]']],[30,85,190,223]),Spacer(1,7),p('These are the fixed phase-delivery endpoint extrapolations, not the later finite-pair common-ξ crossings in 3D. The 4D leading endpoint fit has p≈0.036 and remains exploratory; all sensitivity unions are descriptive.','SmallXY'),h('References and reproducibility'),p('[1] Chester et al., JHEP 06 (2020) 142, arXiv:1912.03324, Table 1 / Eq. 40. [2] Bietenholz, Gerber & Rejón-Barrera, JSTAT (2013) P12009, arXiv:1307.0485. [3] Above-upper-critical-dimension background: Chen-Dohm, cond-mat/9809394; Wittmann-Young, arXiv:1410.5296. Tree comparison: supplied constrained_xy_large_d_note.pdf, pp. 2 and 5: (2d-1)v1=1, v1=∫ exp(β cosθ)cosθ dθ / ∫ exp(β cosθ)dθ on [-ε,ε]. It is a tree instability approximation, not an exact hypercubic curve.','SmallXY'),p('Companion bundle: 13 figures in PNG/PDF/SVG, a captioned atlas, numerical tables, captions and SHA-256 provenance. Source snapshots: phase delivery 20261014-182254; local-xi response 20261015-213702; dimension readout 20261015-224446. All observable/RNG/winding histories, exact checkpoints and logs are preserved; field-only retention does not remove the observable series used here.','SmallXY')]
